package api

var sswCurriculumRoadTransportScenariosEnglish = map[examSSWEnglishKey]string{
	{field: "ssw.scenario", source: `Bus berhenti karena ada tanda gangguan; penumpang meminta kepastian waktu berangkat.`}:                                                                          `The bus has stopped because a fault indicator appeared; a passenger asks when it will depart.`,
	{field: "ssw.scenario", source: `Dokumen mencatat 12 kotak, tetapi di area muat hanya ada 11 kotak berlabel tujuan yang sama.`}:                                                                  `The documents list 12 boxes, but only 11 boxes with the same destination label are at the loading area.`,
	{field: "ssw.scenario", source: `Jadwal menunjukkan layanan bus tetapi kendaraan dan kunci yang diserahkan adalah truk.`}:                                                                        `The schedule shows bus service, but the vehicle and keys handed over are for a truck.`,
	{field: "ssw.scenario", source: `Layar pesanan menunjukkan satu alamat, tetapi penumpang menyebut alamat yang berbeda.`}:                                                                         `The order screen shows one address, but the passenger gives a different one.`,
	{field: "ssw.scenario", source: `Lembar tugas menunjukkan rute biasa, tetapi layar informasi terminal menampilkan pengalihan.`}:                                                                  `The duty sheet shows the usual route, but the terminal information screen shows a diversion.`,
	{field: "ssw.scenario", source: `Pengemudi merasa mengantuk saat masih ada sisa rute.`}:                                                                                                          `The driver feels drowsy with part of the route still remaining.`,
	{field: "ssw.scenario", source: `Penumpang tiba-tiba mengeluh pusing dan meminta kendaraan berhenti.`}:                                                                                           `A passenger suddenly says they feel dizzy and asks the vehicle to stop.`,
	{field: "ssw.scenario", source: `Satu paket belum diserahkan karena penerima tidak tersedia saat pengantaran.`}:                                                                                  `One package could not be delivered because the recipient was unavailable.`,
	{field: "ssw.scenario", source: `Sebelum berangkat, lampu peringatan pada panel menyala dan jadwal mulai segera.`}:                                                                               `Before departure, a warning light comes on and the scheduled start time is near.`,
	{field: "ssw.scenario", source: `Seorang penumpang naik perlahan dan masih berdiri dekat pintu ketika bus akan berangkat.`}:                                                                      `A passenger boards slowly and is still standing near the door when the bus is about to leave.`,
	{field: "ssw.scenario", source: `Setelah perjalanan, terminal pembayaran tidak menampilkan konfirmasi dan penumpang bertanya apakah sudah dibayar.`}:                                             `After the trip, the payment terminal shows no confirmation, and the passenger asks whether payment went through.`,
	{field: "ssw.scenario", source: `Truk tiba tetapi gudang penerima tutup; telepon kontak belum dijawab.`}:                                                                                         `The truck arrives, but the receiving warehouse is closed and the contact has not answered the phone.`,
	{field: "ssw.response", source: `Amankan kendaraan dan muatan di lokasi yang sesuai, hubungi pengatur sesuai prosedur, catat waktu dan upaya kontak, lalu tunggu keputusan.`}:                    `Secure the vehicle and cargo at a suitable location, contact the dispatcher under procedure, record the time and contact attempts, then wait for a decision.`,
	{field: "ssw.response", source: `Cari cara berhenti yang aman sesuai situasi, hubungi pengatur, dan ikuti arahan untuk istirahat atau penggantian sebelum melanjutkan.`}:                         `Find a safe way to stop for the situation, contact the dispatcher, and follow directions about resting or changing drivers before continuing.`,
	{field: "ssw.response", source: `Catat paket sebagai belum terkirim, ikuti tempat penyimpanan yang disetujui, dan serahkan status kepada pengatur untuk penjadwalan berikutnya.`}:                `Record the package as undelivered, use an approved storage location, and give the status to the dispatcher for rescheduling.`,
	{field: "ssw.response", source: `Hentikan kendaraan di tempat aman bila dapat dilakukan, tanyakan kebutuhan bantuan, dan hubungi pihak yang ditentukan oleh prosedur perusahaan.`}:               `Stop the vehicle in a safe place if possible, ask what help is needed, and contact the party specified by company procedure.`,
	{field: "ssw.response", source: `Ikuti prosedur, hubungi petugas operasi, dan beri tahu penumpang bahwa informasi waktu akan disampaikan setelah dikonfirmasi.`}:                                 `Follow procedure, contact operations staff, and tell passengers that timing information will be shared once confirmed.`,
	{field: "ssw.response", source: `Jangan berangkat. Tunjukkan perbedaan itu kepada pengatur, minta penugasan dan kendaraan dicocokkan, lalu pastikan kembali sebelum bekerja.`}:                   `Do not depart. Show the discrepancy to the dispatcher, ask them to match the assignment with the vehicle, and reconfirm before starting work.`,
	{field: "ssw.response", source: `Jangan memilih sendiri salah satunya. Hubungi petugas operasi, ulangi informasi yang berbeda, dan tunggu rute yang dikonfirmasi.`}:                              `Do not choose one route yourself. Contact operations staff, repeat the conflicting information, and wait for a confirmed route.`,
	{field: "ssw.response", source: `Jangan menyatakan muatan lengkap. Pisahkan kelompok itu, catat jumlah yang ditemukan, lalu minta petugas memastikan kotak yang kurang sebelum truk berangkat.`}: `Do not report the load as complete. Keep the group separate, record the number found, and ask staff to confirm the missing box before the truck departs.`,
	{field: "ssw.response", source: `Periksa status transaksi sesuai prosedur perusahaan, jelaskan bahwa Anda sedang memastikan, dan hubungi petugas bila hasilnya belum jelas.`}:                    `Check the transaction status under company procedure, explain that you are confirming it, and contact staff if the result remains unclear.`,
	{field: "ssw.response", source: `Tahan keberangkatan, catat lampu yang terlihat, dan segera laporkan kepada pengatur. Ikuti keputusan pemeriksaan; jangan menghapus peringatan sendiri.`}:        `Hold departure, record which warning light is on, and report it to the dispatcher immediately. Follow the inspection decision; do not clear the warning yourself.`,
	{field: "ssw.response", source: `Tunggu sampai penumpang berada pada keadaan aman sesuai prosedur, amati area pintu, lalu berangkat setelah aman.`}:                                              `Wait until the passenger is in a safe position under procedure, watch the doorway, and depart only when it is safe.`,
	{field: "ssw.response", source: `Ulangi alamat pada layar dan alamat yang diucapkan, lalu minta penumpang memastikan tujuan yang benar sebelum berangkat.`}:                                      `Repeat the address shown on the screen and the one the passenger gave, then ask them to confirm the correct destination before departure.`,
}
